mapper.select:
SELECT r.id, r.space_id AS spaceId, r.source_doc_id AS sourceDocId, r.target_doc_id AS targetDocId, r.target_title AS targetTitle, r.relation_type AS relationType, r.resolved, r.weight, r.is_delete AS isDelete FROM kb_relation r WHERE
AND r.source_doc_id IN
#{sid}

SELECT r.id, r.space_id AS spaceId, r.source_doc_id AS sourceDocId, r.target_doc_id AS targetDocId, r.target_title AS targetTitle, r.relation_type AS relationType, r.resolved, r.weight, r.is_delete AS isDelete FROM kb_relation r WHERE AND r.relation_type = 'supersedes'
AND r.target_doc_id IN
#{tid}

SELECT r.id, r.space_id AS spaceId, r.source_doc_id AS sourceDocId, r.target_doc_id AS targetDocId, r.target_title AS targetTitle, r.relation_type AS relationType, r.resolved, r.weight, r.is_delete AS isDelete FROM kb_relation r WHERE AND r.relation_type <> 'supersedes'
AND r.target_doc_id IN
#{tid}

SELECT r.target_doc_id AS targetDocId, COUNT(*) AS cnt FROM kb_relation r WHERE r.is_delete = 0 AND r.resolved = 1 AND r.target_doc_id IS NOT NULL
AND r.space_id IN
#{sid}
AND r.target_doc_id IN
#{tid}
GROUP BY r.target_doc_id
